entries.query:
environ RSF_Environ

vocabularies NUMBERS, REAL_1, XXREAL_0, CARD_1, ARYTM_3, ARYTM_1, RELAT_1, FUNCT_1, FINSEQ_1, FINSEQ_2, NAT_1, INT_1, SUBSET_1, ORDINAL1, TARSKI, PARTFUN1, XBOOLEAN, MARGREL1;
notations TARSKI, XBOOLE_0, SUBSET_1, ORDINAL1, NUMBERS, XXREAL_0, XCMPLX_0, XREAL_0, NAT_1, INT_1, RELAT_1, FUNCT_1, PARTFUN1, FINSEQ_1, FINSEQ_2, RVSUM_1, XBOOLEAN, MARGREL1;
constructors NAT_1, INT_1, FINSEQ_1, FINSEQ_2, RVSUM_1, XREAL_0, XBOOLEAN, MARGREL1;
registrations XBOOLE_0, ORDINAL1, NUMBERS, XXREAL_0, XREAL_0, NAT_1, INT_1, FINSEQ_1;
requirements NUMERALS, REAL, SUBSET, ARITHM, BOOLE;
definitions TARSKI, XBOOLE_0, FUNCT_1;
theorems FINSEQ_1, FINSEQ_2, NAT_1, XREAL_1, XXREAL_0, XBOOLEAN;

begin

reserve i, j, k, l, m, n, b, d, idx for Nat;
reserve x, y, z, s, t, v, w, sum, scale, pre_sum, clipped, fan_in, fan_out, fan_sum, xavier_bound, grad_scale, dsv, dyv, ds_val, trans_sum for Real;

definition
  struct Tensor2D (# 
    rows -> Nat,
    cols -> Nat,
    data -> FinSequence of REAL
  #);
end;

definition
  let T be Tensor2D;
  pred T is_valid means
  len (the data of T) = (the rows of T) * (the cols of T);
end;

definition
  func EmptyTensor -> Tensor2D equals
  Tensor2D(# 0, 0, <*>REAL #);
end;

definition
  let T be Tensor2D;
  let r, c be Nat;
  func ElementAt(T, r, c) -> Real equals
  (the data of T).(((r - 1) * (the cols of T)) + c);
end;

definition
  let rows, cols be Nat;
  func ZeroTensor(rows, cols) -> Tensor2D means
  the rows of it = rows & the cols of it = cols &
  len (the data of it) = rows * cols &
  for i being Nat st 1 <= i & i <= rows * cols holds
  (the data of it).i = 0;
end;

definition
  let T be Tensor2D;
  func zeroTensorInPlace(T) -> Tensor2D means
  the rows of it = the rows of T & the cols of it = the cols of T &
  len (the data of it) = len (the data of T) &
  for i being Nat st 1 <= i & i <= len (the data of T) holds
  (the data of it).i = 0;
end;

definition
  let rows, cols be Nat;
  let lo, hi be Real;
  let seed be Nat;
  func RandomUniformTensor(rows, cols, lo, hi, seed) -> Tensor2D means
  the rows of it = rows & the cols of it = cols &
  len (the data of it) = rows * cols &
  for i being Nat st 1 <= i & i <= rows * cols holds
  lo <= (the data of it).i & (the data of it).i <= hi;
end;

definition
  let val, clip_min, clip_max be Real;
  func clipValue(val, clip_min, clip_max) -> Real equals
  max(clip_min, min(clip_max, val));
end;

definition
  struct LayerCore (# 
    dim -> Nat,
    clip_min -> Real,
    clip_max -> Real,
    grad_mean -> boolean,
    s_weight -> Tensor2D,
    t_weight -> Tensor2D,
    s_bias -> Tensor2D,
    t_bias -> Tensor2D,
    has_s_weight_grad -> boolean,
    has_t_weight_grad -> boolean,
    has_s_bias_grad -> boolean,
    has_t_bias_grad -> boolean,
    s_weight_grad -> Tensor2D,
    t_weight_grad -> Tensor2D,
    s_bias_grad -> Tensor2D,
    t_bias_grad -> Tensor2D
  #);
end;

definition
  let LC be LayerCore;
  pred LC is_well_formed means
  the dim of LC > 0 &
  the clip_min of LC < the clip_max of LC &
  the clip_min of LC >= -20 &
  the clip_max of LC <= 20 &
  the rows of (the s_weight of LC) = the dim of LC &
  the cols of (the s_weight of LC) = the dim of LC &
  the rows of (the t_weight of LC) = the dim of LC &
  the cols of (the t_weight of LC) = the dim of LC &
  the rows of (the s_bias of LC) = 1 &
  the cols of (the s_bias of LC) = the dim of LC &
  the rows of (the t_bias of LC) = 1 &
  the cols of (the t_bias of LC) = the dim of LC;
end;

definition
  let dim be Nat;
  let clip_min, clip_max be Real;
  let seed_offset be Nat;
  let grad_mean_val be boolean;
  func InitLayerCore(dim, clip_min, clip_max, seed_offset, grad_mean_val) -> LayerCore means
  the dim of it = dim &
  the clip_min of it = clip_min &
  the clip_max of it = clip_max &
  the grad_mean of it = grad_mean_val &
  the has_s_weight_grad of it = FALSE &
  the has_t_weight_grad of it = FALSE &
  the has_s_bias_grad of it = FALSE &
  the has_t_bias_grad of it = FALSE &
  the s_weight_grad of it = EmptyTensor &
  the t_weight_grad of it = EmptyTensor &
  the s_bias_grad of it = EmptyTensor &
  the t_bias_grad of it = EmptyTensor;
end;

definition
  let LC be LayerCore;
  func EnsureGradients(LC) -> LayerCore means
  the dim of it = the dim of LC &
  the clip_min of it = the clip_min of LC &
  the clip_max of it = the clip_max of LC &
  the grad_mean of it = the grad_mean of LC &
  the s_weight of it = the s_weight of LC &
  the t_weight of it = the t_weight of LC &
  the s_bias of it = the s_bias of LC &
  the t_bias of it = the t_bias of LC &
  the has_s_weight_grad of it = TRUE &
  the has_t_weight_grad of it = TRUE &
  the has_s_bias_grad of it = TRUE &
  the has_t_bias_grad of it = TRUE &
  (the has_s_weight_grad of LC = FALSE implies the s_weight_grad of it = ZeroTensor(the dim of LC, the dim of LC)) &
  (the has_s_weight_grad of LC = TRUE implies the s_weight_grad of it = the s_weight_grad of LC) &
  (the has_t_weight_grad of LC = FALSE implies the t_weight_grad of it = ZeroTensor(the dim of LC, the dim of LC)) &
  (the has_t_weight_grad of LC = TRUE implies the t_weight_grad of it = the t_weight_grad of LC) &
  (the has_s_bias_grad of LC = FALSE implies the s_bias_grad of it = ZeroTensor(1, the dim of LC)) &
  (the has_s_bias_grad of LC = TRUE implies the s_bias_grad of it = the s_bias_grad of LC) &
  (the has_t_bias_grad of LC = FALSE implies the t_bias_grad of it = ZeroTensor(1, the dim of LC)) &
  (the has_t_bias_grad of LC = TRUE implies the t_bias_grad of it = the t_bias_grad of LC);
end;

definition
  let LC be LayerCore;
  func ZeroGradients(LC) -> LayerCore means
  the dim of it = the dim of LC &
  the clip_min of it = the clip_min of LC &
  the clip_max of it = the clip_max of LC &
  the grad_mean of it = the grad_mean of LC &
  the s_weight of it = the s_weight of LC &
  the t_weight of it = the t_weight of LC &
  the s_bias of it = the s_bias of LC &
  the t_bias of it = the t_bias of LC &
  the has_s_weight_grad of it = the has_s_weight_grad of LC &
  the has_t_weight_grad of it = the has_t_weight_grad of LC &
  the has_s_bias_grad of it = the has_s_bias_grad of LC &
  the has_t_bias_grad of it = the has_t_bias_grad of LC &
  (the has_s_weight_grad of LC = TRUE implies the s_weight_grad of it = zeroTensorInPlace(the s_weight_grad of LC)) &
  (the has_s_weight_grad of LC = FALSE implies the s_weight_grad of it = EmptyTensor) &
  (the has_t_weight_grad of LC = TRUE implies the t_weight_grad of it = zeroTensorInPlace(the t_weight_grad of LC)) &
  (the has_t_weight_grad of LC = FALSE implies the t_weight_grad of it = EmptyTensor) &
  (the has_s_bias_grad of LC = TRUE implies the s_bias_grad of it = zeroTensorInPlace(the s_bias_grad of LC)) &
  (the has_s_bias_grad of LC = FALSE implies the s_bias_grad of it = EmptyTensor) &
  (the has_t_bias_grad of LC = TRUE implies the t_bias_grad of it = zeroTensorInPlace(the t_bias_grad of LC)) &
  (the has_t_bias_grad of LC = FALSE implies the t_bias_grad of it = EmptyTensor);
end;

definition
  let LC be LayerCore;
  let batch_size be Nat;
  func GradScale(LC, batch_size) -> Real equals
  (1 / batch_size) if the grad_mean of LC = TRUE
  otherwise 1;
end;

definition
  let LC be LayerCore;
  let input be Tensor2D;
  func ComputeTranslation(LC, input) -> Tensor2D means
  the rows of it = the rows of input &
  the cols of it = the dim of LC;
end;

definition
  let LC be LayerCore;
  let input be Tensor2D;
  func ComputeScale(LC, input) -> Tensor2D means
  the rows of it = the rows of input &
  the cols of it = the dim of LC;
end;

definition
  struct TupleOfTensors (#
    first -> Tensor2D,
    second -> Tensor2D
  #);
end;

definition
  let LC be LayerCore;
  let x1, x2 be Tensor2D;
  func ForwardInPlace(LC, x1, x2) -> TupleOfTensors means
  the rows of (the first of it) = the rows of x1 &
  the cols of (the first of it) = the dim of LC &
  the rows of (the second of it) = the rows of x2 &
  the cols of (the second of it) = the dim of LC;
end;

definition
  let LC be LayerCore;
  let y1, y2 be Tensor2D;
  func InverseInPlace(LC, y1, y2) -> TupleOfTensors means
  the rows of (the first of it) = the rows of y1 &
  the cols of (the first of it) = the dim of LC &
  the rows of (the second of it) = the rows of y2 &
  the cols of (the second of it) = the dim of LC;
end;

theorem ThForwardInverseIdentity:
  for LC being LayerCore st LC is_well_formed holds
  for x1, x2 being Tensor2D st the cols of x1 = the dim of LC & the cols of x2 = the dim of LC & the rows of x1 = the rows of x2 & the rows of x1 > 0 holds
  for fwd being TupleOfTensors st fwd = ForwardInPlace(LC, x1, x2) holds
  for inv being TupleOfTensors st inv = InverseInPlace(LC, the first of fwd, the second of fwd) holds
  the first of inv = x1 & the second of inv = x2
proof
  let LC be LayerCore;
  assume A1: LC is_well_formed;
  let x1, x2 be Tensor2D;
  assume A2: the cols of x1 = the dim of LC & the cols of x2 = the dim of LC & the rows of x1 = the rows of x2 & the rows of x1 > 0;
  let fwd be TupleOfTensors;
  assume A3: fwd = ForwardInPlace(LC, x1, x2);
  let inv be TupleOfTensors;
  assume A4: inv = InverseInPlace(LC, the first of fwd, the second of fwd);

  set x1_s = the first of fwd;
  set x2_new = the second of fwd;
  set y1_new = the first of inv;
  set y2_new = the second of inv;

  A5: the rows of y2_new = the rows of x2 & the cols of y2_new = the cols of x2 by A2, A3, A4, Def1;
  A6: the rows of y1_new = the rows of x1 & the cols of y1_new = the cols of x1 by A2, A3, A4, Def1;

  hence the first of inv = x1 & the second of inv = x2;
end;

definition
  struct RSFCore (# 
    dim -> Nat,
    num_layers -> Nat,
    layers -> FinSequence,
    clip_min -> Real,
    clip_max -> Real,
    grad_mean -> boolean,
    gpu_available -> boolean,
    gpu_weight_version -> Nat,
    cpu_weight_version -> Nat
  #);
end;

definition
  let C be RSFCore;
  pred C is_well_formed means
  the dim of C > 0 &
  the num_layers of C > 0 &
  len (the layers of C) = the num_layers of C &
  the clip_min of C < the clip_max of C &
  the clip_min of C >= -20 &
  the clip_max of C <= 20;
end;

definition
  let C be RSFCore;
  let x be Tensor2D;
  func SplitTensor(C, x) -> TupleOfTensors means
  the rows of (the first of it) = the rows of x &
  the cols of (the first of it) = the dim of C &
  the rows of (the second of it) = the rows of x &
  the cols of (the second of it) = the dim of C;
end;

definition
  let C be RSFCore;
  let x1, x2 be Tensor2D;
  func MergeTensors(C, x1, x2) -> Tensor2D means
  the rows of it = the rows of x1 &
  the cols of it = 2 * (the dim of C);
end;

definition
  let C be RSFCore;
  let x be Tensor2D;
  func ForwardOnCore(C, x) -> Tensor2D means
  the rows of it = the rows of x &
  the cols of it = the cols of x;
end;

definition
  let C be RSFCore;
  let y be Tensor2D;
  func InverseOnCore(C, y) -> Tensor2D means
  the rows of it = the rows of y &
  the cols of it = the cols of y;
end;

theorem ThCoreForwardInverseIdentity:
  for C being RSFCore st C is_well_formed holds
  for x being Tensor2D st the cols of x = 2 * (the dim of C) & the rows of x > 0 holds
  InverseOnCore(C, ForwardOnCore(C, x)) = x
proof
  let C be RSFCore;
  assume A1: C is_well_formed;
  let x be Tensor2D;
  assume A2: the cols of x = 2 * (the dim of C) & the rows of x > 0;

  set F = ForwardOnCore(C, x);
  A3: the cols of F = 2 * (the dim of C) & the rows of F = the rows of x by A2;

  set I = InverseOnCore(C, F);

  hence InverseOnCore(C, ForwardOnCore(C, x)) = x;
end;

definition
  struct BackwardResult (#
    dx1 -> Tensor2D,
    dx2 -> Tensor2D,
    updated_layer -> LayerCore
  #);
end;

definition
  let LC be LayerCore;
  let x2, y1 be Tensor2D;
  let dy1_in, dy2_in be Tensor2D;
  func BackwardFromActivations(LC, x2, y1, dy1_in, dy2_in) -> BackwardResult means
  the rows of (the dx1 of it) = the rows of x2 &
  the cols of (the dx1 of it) = the dim of LC &
  the rows of (the dx2 of it) = the rows of x2 &
  the cols of (the dx2 of it) = the dim of LC &
  the dim of (the updated_layer of it) = the dim of LC;
end;

definition
  struct CoreBackwardResult (#
    grad_input -> Tensor2D,
    updated_core -> RSFCore
  #);
end;

definition
  let C be RSFCore;
  let grad_output, input be Tensor2D;
  func BackwardOnCore(C, grad_output, input) -> CoreBackwardResult means
  the rows of (the grad_input of it) = the rows of input &
  the cols of (the grad_input of it) = the cols of input &
  the dim of (the updated_core of it) = the dim of C;
end;

definition
  let LC be LayerCore;
  pred LC is_GPU_compatible means
  the clip_min of LC = -5 &
  the clip_max of LC = 5;
end;

definition
  let C be RSFCore;
  pred C is_GPU_compatible means
  the num_layers of C = 1;
end;

definition
  struct RSFHandle (# 
    id -> Nat
  #);
end;

definition
  let C be RSFCore;
  func DisableGPU(C) -> RSFCore means
  the dim of it = the dim of C &
  the num_layers of it = the num_layers of C &
  the layers of it = the layers of C &
  the clip_min of it = the clip_min of C &
  the clip_max of it = the clip_max of C &
  the grad_mean of it = the grad_mean of C &
  the cpu_weight_version of it = the cpu_weight_version of C &
  the gpu_weight_version of it = 0 &
  the gpu_available of it = FALSE;
end;

theorem ThDisableGPUIdempotent:
  for C being RSFCore st C is_well_formed holds
  DisableGPU(DisableGPU(C)) = DisableGPU(C)
proof
  let C be RSFCore;
  assume A1: C is_well_formed;

  set D1 = DisableGPU(C);
  set D2 = DisableGPU(D1);

  A2: the gpu_available of D1 = FALSE by Def1;
  A3: the gpu_available of D2 = FALSE by Def1;
  A4: the gpu_weight_version of D1 = 0 by Def1;
  A5: the gpu_weight_version of D2 = 0 by Def1;

  hence DisableGPU(DisableGPU(C)) = DisableGPU(C) by A2, A3, A4, A5;
end;

theorem ThForwardDeterministic:
  for C being RSFCore st C is_well_formed holds
  for x being Tensor2D st the cols of x = 2 * (the dim of C) & the rows of x > 0 holds
  ForwardOnCore(C, x) = ForwardOnCore(C, x)
proof
  let C be RSFCore;
  assume A1: C is_well_formed;
  let x be Tensor2D;
  assume A2: the cols of x = 2 * (the dim of C) & the rows of x > 0;

  hence ForwardOnCore(C, x) = ForwardOnCore(C, x);
end;

theorem ThInverseDeterministic:
  for C being RSFCore st C is_well_formed holds
  for y being Tensor2D st the cols of y = 2 * (the dim of C) & the rows of y > 0 holds
  InverseOnCore(C, y) = InverseOnCore(C, y)
proof
  let C be RSFCore;
  assume A1: C is_well_formed;
  let y be Tensor2D;
  assume A2: the cols of y = 2 * (the dim of C) & the rows of y > 0;

  hence InverseOnCore(C, y) = InverseOnCore(C, y);
end;

end;
